import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    skewness = 0.047
    return x1**2 + x2**2 + skewness * (x1 + x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function for global optimization.
    """
    return np.sum(x**2) + 0.047 * np.sum(x)

