import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return float(0.3 * x1**2 + 0.2 * x2**2 + 0.1 * np.sin(2 * x1) + 0.1 * x1 + 0.05 * x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = x / 5.0
    quadratic_term = np.sum(x**2)
    linear_term = np.tanh(5 * x[0]) if x.shape[0] > 0 else 0.0
    return float(0.6 * quadratic_term + 0.4 * linear_term + 0.5)

