import numpy as np

def problem(x: np.ndarray) -> float:
    c = 2.0
    return np.sum((x - c)**2) + np.arcsinh(x[0]) * np.sin(x[1])

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining parts of Ackley and Rosenbrock functions with domain scaling.
    """
    x = x / 2.5  # Scale input to [-2, 2] range (approx.)
    n = x.shape[0]

    ackley_part = -20 * np.exp(-0.2 * np.sqrt(np.mean(x**2))) - np.exp(np.mean(np.cos(2 * np.pi * x))) + 20 + np.exp(1)

    if n > 1:
        rosenbrock_part = np.sum(100 * (x[1:] - x[:-1]**2)**2 + (1 - x[:-1])**2)
    else:
        rosenbrock_part = 0.0

    scaled_rosenbrock = 0.1 * rosenbrock_part # Reduce rosenbrock influence;

    return float(0.7 * ackley_part + 0.3 * scaled_rosenbrock)
